 private int tab,generation,etfLimit=30,quoteToken,etfRequestGeneration;private String coin="BTC",period="4h",reportPeriod="daily",etfCoin="BTC",lessonId="",reportId="",etfRange="全部";private boolean active,refreshing,quoteRefreshing,reportsRefreshing,etfRefreshing,resumeNeedsRender;private int restoreScrollY=-1;
 private long multiAt,reportAt,chartAt,etfAt,lastQuoteAt;private Future<?> quoteRequest;private final Map<String,TextView> periodViews=new LinkedHashMap<>();private final List<Future<?>> pending=new ArrayList<>();
