 @Override protected void onSaveInstanceState(Bundle b){b.putInt("tab",tab);b.putString("coin",coin);b.putString("period",period);b.putString("lesson",lessonId);b.putString("etfCoin",etfCoin);b.putString("etfRange",etfRange);b.putString("reportPeriod",reportPeriod);b.putString("reportId",reportId);b.putInt("etfLimit",etfLimit);b.putInt("scrollY",scroll.getScrollY());if(reports!=null&&reports.toString().length()<=100000)b.putString("reports",reports.toString());super.onSaveInstanceState(b);}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);tab=i.getIntExtra("tab",tab);if(tab<0||tab>4)tab=0;lessonId="";reportId="";restoreScrollY=-1;render();}
 @Override protected void onResume(){super.onResume();active=true;quoteRefreshing=false;if(resumeNeedsRender){resumeNeedsRender=false;render();restoreScroll();}main.removeCallbacks(tick);main.post(tick);}
 @Override protected void onPause(){active=false;restoreScrollY=scroll.getScrollY();resumeNeedsRender=true;generation++;main.removeCallbacks(tick);for(Future<?> f:pending)f.cancel(true);pending.clear();if(quoteRequest!=null)quoteRequest.cancel(true);quoteToken++;refreshing=quoteRefreshing=reportsRefreshing=etfRefreshing=false;prefs.edit().putString("coin",coin).putString("period",period).putString("etfCoin",etfCoin).putString("etfRange",etfRange).apply();super.onPause();}
 @Override protected void onDestroy(){generation++;quoteToken++;if(quoteRequest!=null)quoteRequest.cancel(true);for(Future<?>f:pending)f.cancel(true);main.removeCallbacksAndMessages(null);super.onDestroy();}
 private void restoreScroll(){if(restoreScrollY<0)return;if(tab==1&&reportId.isEmpty()&&(reportList==null||reportList.getChildCount()==0))return;if(tab==3&&etfData==null)return;final int y=restoreScrollY,g=generation;restoreScrollY=-1;scroll.getViewTreeObserver().addOnPreDrawListener(new ViewTreeObserver.OnPreDrawListener(){public boolean onPreDraw(){if(scroll.getViewTreeObserver().isAlive())scroll.getViewTreeObserver().removeOnPreDrawListener(this);if(g==generation&&!isDestroyed())scroll.scrollTo(0,y);return true;}});}
 @Override public void onBackPressed(){goBack();}private void goBack(){if(!lessonId.isEmpty()){lessonId="";render();}else if(!reportId.isEmpty()){reportId="";render();}else if(tab!=0){tab=0;render();}else finish();}
 private <T>void task(Work<T>w,Done<T>d,Done<String>error){int g=generation;pending.removeIf(Future::isDone);Future<?>f=HttpRequests.submit(repo.io,()->{try{T value=w.run();main.post(()->{if(g==generation&&!isDestroyed())try{d.accept(value);}catch(Exception e){error.accept(e.getMessage()==null?"数据显示失败，请重试":e.getMessage());}});}catch(Exception e){String msg=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();main.post(()->{if(g==generation&&!isDestroyed())error.accept(msg);});}});pending.add(f);}
 private void render(){generation++;refreshing=reportsRefreshing=etfRefreshing=false;for(Future<?>f:pending)f.cancel(true);pending.clear();if(quoteRequest!=null)quoteRequest.cancel(true);quoteToken++;quoteRefreshing=false;body.removeAllViews();nav.removeAllViews();etfData=null;etfRows=null;lastQuoteAt=0;periodViews.clear();String[]names={"行情","研报","看懂","ETF","提醒"};for(int i=0;i<names.length;i++){final int t=i;weighted(nav,new NavItem(this,i,names[i],tab==i,()->{tab=t;lessonId="";reportId="";restoreScrollY=-1;render();}));}status.setText(tab==0?"市场观察":names[tab]);scroll.scrollTo(0,0);
  switch(tab){case 0:market();break;case 1:if(reportId.isEmpty())reports();else reportDetail();break;case 2:if(lessonId.isEmpty())lessons();else lesson();break;case 3:flows();break;case 4:alerts();break;}
 }
