 private void showQuote(Repository.Quote q){lastQuoteAt=q.asOf;quote.setText(n(q.price));quoteChange.setText(String.format(Locale.US,"24h  %+.2f%%",q.change));quoteChange.setTextColor(q.change>0?GREEN:q.change<0?RED:MUTED);quoteMeta.setText((q.cached?"历史快照 · ":"来源 · ")+quoteTime(q.asOf));}
 private void showBars(Repository.Bars b,String p){chart.data(b.bars,b.points);interpretation.setText(explain(b.analysis));status.setText(b.cached?"历史行情":"行情已更新");TextView selected=periodViews.get(p);if(selected!=null)selected.setText(label(p)+" · "+(b.cached?"历史 · ":"")+(b.analysis.valid()?b.analysis.trend:b.analysis.reason));}
 private void refreshMarket(boolean force){if(refreshing||tab!=0)return;refreshing=true;String c=coin,p=period;task(()->repo.bars(c,p),b->{refreshing=false;showBars(b,p);},e->{refreshing=false;status.setText("等待联网");interpretation.setText("连接暂不可用，历史行情仅供回看，暂停新信号。");});long now=System.currentTimeMillis();if(force||now-multiAt>60000){multiAt=now;for(String pp:Market.PERIODS){if(pp.equals(p))continue;TextView v=periodViews.get(pp);task(()->repo.bars(c,pp),b->{if(v!=null)v.setText(label(pp)+"  ·  "+(b.cached?"历史 · ":"")+(b.analysis.valid()?b.analysis.trend+"\n"+b.analysis.structure:b.analysis.reason));},e->{if(v!=null)v.setText(label(pp)+" · 来源不可用");});}}}
 private String explain(Market.Analysis a){if(!a.valid())return a.reason+"\n缓存与未闭合数据不产生新信号。";return a.trend+"\n"+a.structure+"\n确认时间  "+time(a.closedAt)+"\n\n"+a.candle+"；相对前收盘 "+String.format(Locale.US,"%+.2f%%",a.change)+"\n相对前 20 根成交量："+n(a.volumeRatio)+" 倍\n\nMACD · "+a.macdText+"\n\nRSI · "+a.rsiText+(a.box==null?"":"\n\n固定箱体 "+n(a.box.low)+" — "+n(a.box.high))+"\n\n价格形态不代表机制健康或个人买卖许可。";}

 private LinearLayout reportList;private void reports(){intro("研究资料","研报","保留每一期的观点、依据与反证。");chips(body,new String[]{"daily","weekly"},reportPeriod,v->{reportPeriod=v;render();});body.addView(button(this,"检查最新研究",false,()->loadReports()));gap(body,14);reportList=column(this);body.addView(reportList);loadReports();LinearLayout note=panel("研究如何更新");expand(note,"发布与更新规则","在维护观潮的项目对话里分析市场，再要求“更新”。核验并发布新一期后，应用会读取；未发布时不会自动编造日报。");}
