 @Override public void onRequestPermissionsResult(int code,String[]p,int[]r){super.onRequestPermissionsResult(code,p,r);if(code==41&&r.length>0&&r[0]==PackageManager.PERMISSION_GRANTED){prefs.edit().putBoolean("alerts",true).putLong("enabledAt",System.currentTimeMillis()).apply();AlertJob.schedule(this);AlertJob.once(this);}if(tab==4)render();}

 private void refreshQuote(){
  if(!active||tab!=0||quoteRefreshing)return;
  quoteRefreshing=true;int g=generation,token=++quoteToken;String symbol=coin;
  quoteRequest=HttpRequests.submit(repo.quotes,()->{
   try{Repository.Quote q=repo.quote(symbol);main.post(()->{
    if(g!=generation||token!=quoteToken||!active||isDestroyed())return;quoteRefreshing=false;
    showQuote(q);
   });}catch(Exception e){main.post(()->{
    if(g!=generation||token!=quoteToken||!active||isDestroyed())return;quoteRefreshing=false;
    quoteMeta.setText(lastQuoteAt>0?"离线 · 历史行情\n来源："+quoteTime(lastQuoteAt):"报价暂不可用 · 请稍后重试");
   });}
  });
 }
 private void loadEtf(){
  if(etfRefreshing)return;etfRefreshing=true;etfAt=System.currentTimeMillis();String symbol=etfCoin;int request=++etfRequestGeneration;
  task(()->repo.localEtf(symbol),p->{if(request!=etfRequestGeneration)return;if(p!=null&&etfData==null){etfData=p.data;etfState.setText(p.state+" · 正在检查更新");drawEtf();}},e->{});
  task(()->repo.etfHistory(symbol),p->{
   if(request!=etfRequestGeneration)return;etfRefreshing=false;etfData=p.data;JSONArray rows=p.data.optJSONArray("rows");int count=rows==null?0:rows.length();
   String start=count==0?"—":rows.optJSONObject(0).optString("date"),end=count==0?"—":rows.optJSONObject(count-1).optString("date");
   etfState.setText(p.state+" · "+count+" 个披露日\n"+start+" 至 "+end+"\n读取时间："+p.data.optString("capturedAt")+"\n单位：百万美元 · 前台每 5 分钟检查披露"+(p.issue.isEmpty()?"":"\n更新失败，显示历史资料："+p.issue));drawEtf();
  },e->{if(request==etfRequestGeneration){etfRefreshing=false;etfState.setText("历史读取失败："+e);}});
 }
 private void drawEtf(){
  if(etfData==null||etfRows==null)return;etfRows.removeAllViews();JSONArray all=etfData.optJSONArray("rows");
  List<JSONObject> selected=new ArrayList<>();java.time.LocalDate end=java.time.LocalDate.now(java.time.ZoneOffset.UTC);
  String since=etfRange.equals("1个月")?end.minusMonths(1).toString():etfRange.equals("3个月")?end.minusMonths(3).toString():etfRange.equals("1年")?end.minusYears(1).toString():"";
  if(all!=null)for(int i=0;i<all.length();i++){JSONObject row=all.optJSONObject(i);if(row!=null&&(since.isEmpty()||row.optString("date").compareTo(since)>=0)&&row.optString("date").compareTo(end.toString())<=0)selected.add(row);}
  selected.sort((x,y)->x.optString("date").compareTo(y.optString("date")));
  double sum=0;int complete=0,partial=0;List<String>dates=new ArrayList<>();List<Double>totals=new ArrayList<>();
  for(JSONObject row:selected){dates.add(row.optString("date"));Double total=row.isNull("total")?null:row.optDouble("total",Double.NaN);totals.add(total);
   if(total!=null&&Double.isFinite(total)&&row.optString("status").equals("complete")){sum+=total;complete++;}else partial++;
  }
  etfSummary.setText(selected.isEmpty()?"所选日期范围没有披露记录。":"已完整披露累计  "+String.format(Locale.US,"%+,.1f",sum)+" 百万美元\n"+complete+" 个完整日"+(partial>0?" · "+partial+" 个未完整披露日不计入累计":""));
  flowChart.data(dates,totals);
  if(selected.isEmpty())para(etfRows,"可切换“全部”查看已有历史。数据源没有提供的日期不会补成零。");
  for(int i=selected.size()-1;i>=Math.max(0,selected.size()-etfLimit);i--){
   JSONObject row=selected.get(i);String flow=row.isNull("total")?"未披露":String.format(Locale.US,"%+,.1f",row.optDouble("total"));
   gap(etfRows,8);etfRows.addView(button(this,row.optString("date")+"     "+flow+(row.optString("status").equals("complete")?"":" · 部分"),false,()->{
    StringBuilder detail=new StringBuilder("单位：百万美元");JSONArray funds=row.optJSONArray("funds");
    if(funds!=null)for(int k=0;k<funds.length();k++){JSONObject fund=funds.optJSONObject(k);if(fund!=null)detail.append("\n").append(fund.optString("ticker")).append("   ").append(fund.isNull("flow")?"未披露":n(fund.optDouble("flow")));}
    new AlertDialog.Builder(this).setTitle(etfCoin+" · "+row.optString("date")).setMessage(detail.toString()).setPositiveButton("完成",null).show();
   }));
  }
  if(selected.size()>etfLimit){gap(etfRows,12);etfRows.addView(button(this,"加载更早记录",false,()->{etfLimit+=30;drawEtf();}));}
  gap(etfRows,12);link(etfRows,"Farside 原始披露表",etfData.optString("source"));link(etfRows,"CoinGlass 对照页",etfData.optString("compare"));restoreScroll();
 }

 private Intent notificationSettingsIntent(){return new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName());}
 private void openAppSettings(){openSettings(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}
 private void openSettings(Intent intent){try{startActivity(intent);}catch(ActivityNotFoundException|SecurityException e){Toast.makeText(this,"请在系统设置中搜索“观潮”",Toast.LENGTH_LONG).show();}}

